<script setup>
import { computed, reactive } from 'vue';
import { router } from '@inertiajs/vue3';
import AppLayout from '../../Layouts/AppLayout.vue';
import DashboardIcon from '../../components/dashboard/DashboardIcon.vue';
import PaginationLinks from '../../components/ui/PaginationLinks.vue';

const props = defineProps({
    type: String, from: String, to: String, summary: Object, analytics: Object,
    statusOptions: Array, data: Object, rows: Array, headings: Array, clients: Array,
    sellers: Array, types: Object, reportMeta: Object, filters: Object, exportUrl: String,
});
const filterState = reactive({ report_type: props.type, start_date: props.from, end_date: props.to, client: props.filters?.client || '', seller: props.filters?.seller || '', status: props.filters?.status || '' });
const money = value => new Intl.NumberFormat('es-NI', { style: 'currency', currency: 'NIO', maximumFractionDigits: 2 }).format(Number(value || 0));
const number = value => new Intl.NumberFormat('es-NI').format(Number(value || 0));
const currentMeta = computed(() => props.reportMeta[props.type] || {});
const trendMax = computed(() => Math.max(...(props.analytics?.trend || []).map(item => Number(item.amount)), 1));
const leaderMax = computed(() => Math.max(...(props.analytics?.leaders || []).map(item => Number(item.amount)), 1));
const isMoneyReport = computed(() => props.type !== 'routes');
const primaryValue = computed(() => isMoneyReport.value ? money(props.summary.primary) : number(props.summary.primary));
const secondaryIsMoney = computed(() => ['portfolio', 'applications', 'disbursements'].includes(props.type));
const secondaryValue = computed(() => secondaryIsMoney.value ? money(props.summary.secondary) : number(props.summary.secondary));
const amount = value => isMoneyReport.value ? money(value) : number(value);
const cleanFilters = () => Object.fromEntries(Object.entries(filterState).filter(([, value]) => value !== '' && value !== null));
const refresh = () => router.get('/reportes', cleanFilters(), { preserveState: true, replace: true });
const selectReport = reportType => router.get('/reportes', { report_type: reportType, start_date: filterState.start_date, end_date: filterState.end_date });
const exportHref = computed(() => `${props.exportUrl}?${new URLSearchParams(cleanFilters()).toString()}`);
const setRange = range => { const end = new Date(); const start = new Date(end); if (range === 'month') start.setDate(1); if (range === 'quarter') start.setDate(start.getDate() - 89); if (range === 'year') start.setMonth(0, 1); const iso = date => date.toISOString().slice(0, 10); filterState.start_date = iso(start); filterState.end_date = iso(end); refresh(); };
const reset = () => { filterState.client = ''; filterState.seller = ''; filterState.status = ''; refresh(); };
</script>

<template>
<AppLayout title="Centro de reportes" eyebrow="Inteligencia gerencial" description="Indicadores confiables para supervisar cartera, operación y desempeño financiero.">
    <template #header-actions><a :href="exportHref" class="report-export"><DashboardIcon name="credit"/> Exportar CSV</a></template>
    <nav class="report-tabs" aria-label="Tipos de reporte"><button v-for="(name, key) in types" :key="key" type="button" :aria-current="type === key ? 'page' : undefined" @click="selectReport(key)"><span>{{ name }}</span><small>{{ reportMeta[key]?.dimension }}</small></button></nav>
    <section class="report-hero"><div><span>REPORTE ACTIVO</span><h2>{{ types[type] }}</h2><p>{{ currentMeta.description }}</p></div><div class="report-period"><small>Período analizado</small><strong>{{ from }} — {{ to }}</strong><span>{{ number(analytics.records) }} registros incluidos</span></div></section>
    <section class="report-filters">
        <div class="quick-ranges"><span>Rango rápido</span><button type="button" @click="setRange('month')">Este mes</button><button type="button" @click="setRange('quarter')">90 días</button><button type="button" @click="setRange('year')">Este año</button></div>
        <div class="filter-fields">
            <label>Desde<input v-model="filterState.start_date" type="date" @change="refresh"></label><label>Hasta<input v-model="filterState.end_date" type="date" @change="refresh"></label>
            <label v-if="['portfolio','collections','applications'].includes(type)">Cliente<select v-model="filterState.client" @change="refresh"><option value="">Todos los clientes</option><option v-for="client in clients" :key="client.id" :value="client.id">{{ client.full_name }}</option></select></label>
            <label v-if="['portfolio','collections','applications','routes'].includes(type)">Responsable<select v-model="filterState.seller" @change="refresh"><option value="">Todos los responsables</option><option v-for="seller in sellers" :key="seller.id" :value="seller.id">{{ seller.user?.name }}</option></select></label>
            <label v-if="statusOptions.length">Estado / resultado<select v-model="filterState.status" @change="refresh"><option value="">Todos</option><option v-for="option in statusOptions" :key="option.value" :value="option.value">{{ option.label }}</option></select></label><button type="button" class="clear-filter" @click="reset">Limpiar filtros</button>
        </div>
    </section>
    <section class="report-kpis">
        <article data-tone="blue"><i><DashboardIcon name="credit"/></i><div><small>Registros analizados</small><strong>{{ number(summary.count) }}</strong><p>Dentro del período y filtros</p></div></article>
        <article data-tone="emerald"><i><DashboardIcon name="cash"/></i><div><small>{{ summary.primary_label }}</small><strong>{{ primaryValue }}</strong><p>{{ currentMeta.metric }}</p></div></article>
        <article data-tone="gold"><i><DashboardIcon name="wallet"/></i><div><small>{{ summary.secondary_label }}</small><strong>{{ secondaryValue }}</strong><p>Indicador complementario</p></div></article>
        <article data-tone="navy"><i><DashboardIcon name="shield"/></i><div><small>Promedio por registro</small><strong>{{ amount(analytics.average_amount) }}</strong><p>Base: {{ number(analytics.records) }} movimientos</p></div></article>
    </section>
    <section class="analytics-grid">
        <article class="analytics-panel trend-panel"><header><div><span>EVOLUCIÓN</span><h3>{{ currentMeta.metric }} por período</h3></div><small>{{ analytics.trend.length }} períodos</small></header><div v-if="analytics.trend.length" class="trend-chart"><div v-for="item in analytics.trend" :key="item.period" :title="`${item.label}: ${amount(item.amount)} · ${item.count} registros`"><b>{{ amount(item.amount) }}</b><i :style="{height:`${Math.max(4, Number(item.amount) / trendMax * 100)}%`}"></i><small>{{ item.label }}</small></div></div><p v-else class="empty-state">No hay información para construir la tendencia.</p></article>
        <article class="analytics-panel distribution-panel"><header><div><span>COMPOSICIÓN</span><h3>Distribución por {{ currentMeta.dimension?.toLowerCase() }}</h3></div></header><div v-if="analytics.distribution.length" class="distribution-list"><div v-for="item in analytics.distribution" :key="item.label"><p><span>{{ item.label }} <small>{{ item.count }} registros</small></span><strong>{{ amount(item.amount) }}</strong></p><i><b :style="{width:`${item.percentage}%`}"></b></i><em>{{ item.percentage }}%</em></div></div><p v-else class="empty-state">Sin categorías disponibles.</p></article>
        <article class="analytics-panel leaders-panel"><header><div><span>CONCENTRACIÓN</span><h3>Principales responsables</h3></div></header><div v-if="analytics.leaders.length" class="leader-list"><div v-for="(leader,index) in analytics.leaders" :key="leader.name"><span>{{ index + 1 }}</span><p><strong>{{ leader.name }}</strong><small>{{ leader.count }} registros</small><i><b :style="{width:`${Math.max(3, Number(leader.amount) / leaderMax * 100)}%`}"></b></i></p><em>{{ amount(leader.amount) }}</em></div></div><p v-else class="empty-state">Sin responsables para el rango seleccionado.</p></article>
    </section>
    <section class="report-table-panel"><header><div><span>DETALLE AUDITABLE</span><h3>{{ types[type] }}</h3><p>Los datos visibles corresponden exactamente a los filtros aplicados.</p></div><a :href="exportHref">Descargar reporte completo →</a></header><div class="report-table-wrap"><table><thead><tr><th v-for="heading in headings" :key="heading">{{ heading }}</th></tr></thead><tbody><tr v-for="row in rows" :key="row.id"><td v-for="(cell,index) in row.cells" :key="index">{{ cell ?? '—' }}</td></tr></tbody></table></div><p v-if="!rows.length" class="empty-state">No hay datos para los filtros seleccionados.</p><PaginationLinks :links="data.links"/></section>
</AppLayout>
</template>

<style scoped>
